-- Transkripte dayalı video soruları: 9YjeB6Be4A8 (MAVLink RGB LED), SgE2sHkjkBs (autotune),
-- jgdnpCDZRPk (toplanabilir iniş takımı). Sorular YouTube transkriptinden (İngilizce çeviri)
-- yazıldı; her sorunun zaman damgası ve kanıt cümlesi aşağıdaki yorumlardadır.
-- Mevcut Uçuş Kontrol & Kurulum quizlerine EKLENİR. Idempotent: aynı soru metni varsa atlanır.

begin;

-- 9YjeB6Be4A8 02:38: We will connect this cable to telemetry 2 port.
-- 9YjeB6Be4A8 03:38: We used telemetry 1 port for ground station already... we need more telemetry output (miniosd, prm02).
-- 9YjeB6Be4A8 12:08: the lights on the back are blinking yellow, because it can not provide gps connection in the house.
-- 9YjeB6Be4A8 08:08: The led on/off control channel... I will set it to Channel 8.
-- SgE2sHkjkBs 01:26: on the cards which use 3.5 version or later as pixhawk autotune can be started from loiter position hold mode which is gps supported.
-- SgE2sHkjkBs 14:27: autotune for roll axis is done and new autotune operation for pitch axis got started... last axis, yaw.
-- jgdnpCDZRPk 01:35: This card will be powered directly from the battery, with 2-6S. From the flight card, it will only get the signal... If this is not the card, we will connect the engines directly to the flight card and we will burn the flight card.
-- jgdnpCDZRPk 15:55: I get rtl mode... it rises to 15m... when it is at 15 meters, it automatically takes the collectable legs into the landing position.
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'Uçuş Kontrol & Kurulum' and z.zorluk = 'orta' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: Uçuş Kontrol & Kurulum orta'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Videodaki MAVLink RGB LED kontrol kartı Pixhawk üzerinde hangi porta bağlanır?","a":"TELEM 1 yer istasyonu için kullanıldığından LED kartı TELEM 2'ye bağlanır.","o":[["TELEM 1 portuna",false],["TELEM 2 portuna",true],["GPS portuna",false],["I2C portuna",false]]},{"m":"LED kartı üzerinde neden iki telemetri çıkışı vardır?","a":"Kart TELEM 2'den aldığı veriyi bir çıkıştan yeniden sunar; bu sayede miniOSD veya PRM02 de bağlanabilir.","o":[["Aynı telemetri verisini ikinci bir modüle (miniOSD, PRM02) aktarabilmek için",true],["İki LED grubunu ayrı ayrı beslemek için",false],["Pil gerilimini iki kez ölçmek için",false],["GPS ve pusula verisini ayırmak için",false]]},{"m":"Evde (kapalı alanda) denemede arka LED'ler neden sarı yanıp söner?","a":"GPS fix olduğunda arka LED'ler yeşil yanıp söner, fix yokken sarı yanıp söner.","o":[["GPS bağlantısı (fix) sağlanamadığı için",true],["Pil zayıfladığı için",false],["Kumanda kapalı olduğu için",false],["LED kartı arızalı olduğu için",false]]},{"m":"Videoda LED sisteminin kumandadan açılıp kapatılması için hangi kanal seçilmiştir?","a":"LED açma/kapama kanalı olarak 8. kanal seçilmiş ve tüm sistem buradan toplu olarak kontrol edilmiştir.","o":[["Kanal 5",false],["Kanal 6",false],["Kanal 7",false],["Kanal 8",true]]},{"m":"Videoya göre 3.5 ve üzeri yazılımlı Pixhawk'ta autotune hangi moddan başlatılabilir?","a":"APM (3.5 ve öncesi) yalnızca AltHold'dan başlatabilirken Pixhawk'ta GPS destekli moddan başlatılabilir.","o":[["Yalnızca AltHold'dan",false],["GPS destekli Loiter / Position Hold modundan",true],["Yalnızca Stabilize'dan",false],["Yalnızca RTL'den",false]]},{"m":"Autotune uçuşunda eksenler hangi sırayla ayarlanır?","a":"Önce roll, sonra pitch, en son yaw ekseni için tune yapılır.","o":[["Yaw, pitch, roll",false],["Roll, pitch, yaw",true],["Pitch, yaw, roll",false],["Hepsi aynı anda",false]]},{"m":"HML650 setindeki kontrol kartı neden önemlidir?","a":"Kart 2-6S pilden beslenir; motor akımı uçuş kartının çıkışlarından geçmez.","o":[["İniş takımı motorlarını doğrudan pilden besler, uçuş kartından yalnızca açma/kapama sinyali alır; aksi halde uçuş kartı yanabilir",true],["Yalnızca LED'leri kontrol eder",false],["GPS sinyalini güçlendirir",false],["Pil gerilimini düşürür",false]]},{"m":"RTL modunda deneme sırasında iniş takımı ne zaman otomatik olarak inme konumuna alınır?","a":"LGR deploy/retract ayarları sayesinde Pixhawk RTL/Land'de bacakları kendisi indirir.","o":[["Kalkış noktasına dönerken 15 m irtifada",true],["Kalkıştan hemen sonra",false],["Pil bitince",false],["Yer istasyonu komutuyla",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

-- 9YjeB6Be4A8 05:43: The rx of this card is the tx of this card. We have to cross combine the tx of this to the rx of this.
-- 9YjeB6Be4A8 06:50: if it goes down to 10.5 volts... if the battery level drops below 10.5v, the rear LEDs will turn red.
-- 9YjeB6Be4A8 07:46: in case of rc lost, we see the blue light of the leds.
-- 9YjeB6Be4A8 10:57: we enter the full parameter list... write SR2 in the search area. We then set the first parameter staying as 2...
-- 9YjeB6Be4A8 01:23: PT1 and PT2... controlled with a channel assigned through the software... when the circuit is on, it applies a voltage of 5 volts.
-- 9YjeB6Be4A8 09:54: I took out the white part of this cable, i.e. the signal part... only +/- parts... connect it to the esc's... This cable will not pass any signal.
-- SgE2sHkjkBs 01:48: If we start autotune from the mode gps supported, it would realise autotune in 5 meters radius circle... drone might have drifted and gone far away.
-- SgE2sHkjkBs 04:03: the value is 7 which means autotunes for all axes... choose them as binary combinations.
-- SgE2sHkjkBs 04:32: The max value is 0.1 and the minimum is 0.05... if we choose the value 0.1, drone would severely response.
-- SgE2sHkjkBs 06:20: If I observe that drone has very strict reactions... I decrease autotune aggressiveness and start again the operation autotune from the beginning.
-- SgE2sHkjkBs 07:31: rc_feel... decreases the effects of commands only from the controller on drone without changing its pid settings. Its value is between 0 and 100. Its default value is 50. We can decrease it to 25.
-- SgE2sHkjkBs 08:19: if the propellers... are 13inch or above, we should change the FILT value as 10 which is located in the roll and pitch.
-- SgE2sHkjkBs 10:12: If the motors need more amper than we write there, the pixhawk flight card prevents battery from being stayed 5sec on that amper by decreasing drone's throotle value.
-- SgE2sHkjkBs 12:00: As I use 4s battery, I configure that 16.8 volt. As the min level... I enter 12.8 by calculating 3.2 per cell.
-- SgE2sHkjkBs 13:24: All joysticks should be at middle to turn on autotune mode. If trim settings and joysticks aren't neutral position; the autotune wouldn't start.
-- SgE2sHkjkBs 15:08: If I turn off the switch... drone will return its old PID settings. If I pull down it without turning off, and disarm, it will save its new PID settings.
-- jgdnpCDZRPk 06:57: we can make collectible landing gear here from AUX1 to 4 to any one of them we want. But we can not do aux 5 and 6.
-- jgdnpCDZRPk 08:32: the first 8 of them correspond to mainout. From here, the auxes start. aux1 corresponds to servo9.
-- jgdnpCDZRPk 08:55: servo9 function is 0, which means it is disabled. We will change this to landing gear, 29.
-- jgdnpCDZRPk 11:13: When the card first starts to work, it will protect the legs regardless of the position of the switch... the first commands we give will not apply to the legs.
-- jgdnpCDZRPk 14:21: the flight card will send 1100 value to the legs at the time of landing, and 1900 value at the time of flight and the legs will be collected.
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'Uçuş Kontrol & Kurulum' and z.zorluk = 'zor' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: Uçuş Kontrol & Kurulum zor'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"LED kartının ayarları FTDI aracıyla yapılırken seri pinler nasıl bağlanır?","a":"Seri haberleşmede bir tarafın TX'i diğer tarafın RX'ine bağlanmalıdır.","o":[["TX-TX ve RX-RX doğrudan",false],["FTDI'nin TX'i kartın RX'ine, RX'i kartın TX'ine (çapraz)",true],["Yalnızca GND ve VCC bağlanır",false],["Yalnızca TX hattı bağlanır",false]]},{"m":"Videodaki ayara göre pil gerilimi 10.5 V altına düşünce arka LED'ler ne yapar?","a":"Battery alarm voltage 10.5 V olarak girilmiştir; altında arka LED'ler kırmızıya döner.","o":[["Kırmızı yanar",true],["Mavi yanıp söner",false],["Sarı yanıp söner",false],["Yeşil sabit yanar",false]]},{"m":"Kumanda bağlantısı kaybolduğunda (RC failsafe) arka LED'ler nasıl görünür?","a":"RC kaybında LED'ler mavi yanıp söner; GPS fix yoksa sarı, varsa yeşil yanıp söner.","o":[["Mavi renkte yanıp söner",true],["Kırmızı yanar",false],["Yeşil sabit yanar",false],["Söner",false]]},{"m":"TELEM 2 çıkışının veri akış hızlarını ayarlamak için Full Parameter List'te hangi grup aranır?","a":"TELEM 2 akış hızları SR2 parametre grubundadır; değerler girilip Write'a basılır.","o":[["SR1",false],["SR2",true],["SERIAL2",false],["NTF",false]]},{"m":"LED kartındaki PT1 ve PT2 çıkışları ne işe yarar?","a":"Kart yalnızca 4 LED kanalı kontrol ettiğinden kalan iki kanal için PT1/PT2 çıkışları kullanılabilir.","o":[["Yazılımla atanan bir kanalla açılıp kapanan, açıkken 5 V veren ek çıkışlardır (ör. 5 V çalışan başka LED'ler)",true],["Pil gerilimini ölçen sensör girişleridir",false],["GPS antenini bağlamak için kullanılır",false],["Telemetri hızını ayarlar",false]]},{"m":"LED kartının güç kablosu ESC'ye bağlanırken neden beyaz (sinyal) kablo çıkarılmıştır?","a":"Güç yalnızca +/- uçlarıyla ESC'nin BEC devresinden alınır.","o":[["ESC'nin BEC devresi yalnızca elektrik sağlar, bu kablo sinyal taşımamalıdır",true],["Beyaz kablo tek başına yetersiz akım taşıdığı için",false],["Sinyal kablosu GPS ile karıştığı için",false],["Kablo renk standardı gereği",false]]},{"m":"Autotune'u GPS destekli moddan başlatmanın avantajı nedir?","a":"GPS desteği sayesinde tune sırasında konum korunur; GPS'siz modlarda drone sürüklenip uzaklaşabilir.","o":[["Drone başlangıç noktası merkezli yaklaşık 5 m çaplı alanda kalır, uzağa sürüklenmez",true],["Autotune daha az pil harcar",false],["Autotune süresi yarıya iner",false],["PID değerleri kaydedilmek zorunda kalmaz",false]]},{"m":"AUTOTUNE_AXES değeri 7 olarak girilirse ne olur?","a":"Parametre bir bit maskesidir: roll + pitch + yaw = 7. Eksenler ayrı ayrı veya kombinasyon halinde seçilebilir.","o":[["Yalnızca roll ayarlanır",false],["Roll ve pitch ayarlanır",false],["Roll, pitch ve yaw eksenlerinin üçü de ayarlanır",true],["Yalnızca yaw ayarlanır",false]]},{"m":"Autotune aggressiveness parametresinin sınırları ve yüksek değerin etkisi nedir?","a":"Varsayılan 0.1 en sert değerdir; 0.05 daha yumuşak hareket verir.","o":[["0.05 - 0.1; yüksek değerde tepkiler sert, düşük değerde yumuşak olur",true],["0 - 1; yüksek değerde tepkiler yavaşlar",false],["0.5 - 5; değer etkisizdir",false],["0.1 - 1; yüksek değerde autotune daha uzun sürer",false]]},{"m":"Autotune sonrası test uçuşunda drone çok sert tepki veriyorsa videoda hangi yol izlenir?","a":"Sert tepki aggressiveness değerinin yüksekliğinden kaynaklanır; değer düşürülüp autotune tekrarlanır.","o":[["Aggressiveness düşürülür ve autotune baştan yapılır",true],["Motorlar değiştirilir",false],["Pil gerilimi artırılır",false],["GPS kapatılır",false]]},{"m":"RC_FEEL parametresi için hangisi doğrudur?","a":"Videoda RC_FEEL 50'den 25'e düşürülerek kumanda tepkisinin yumuşatılabileceği söylenir.","o":[["PID kazançlarını değiştirir, 0-10 aralığındadır",false],["PID'e dokunmadan kumanda komutlarının etkisini yumuşatır; 0-100 aralığı, varsayılan 50",true],["Yalnızca yaw eksenini etkiler, varsayılan 0",false],["Autotune'u başlatan anahtardır",false]]},{"m":"Pervaneleri 13 inç ve üzeri olan multikopterde autotune öncesi roll ve pitch rate FILT değeri kaça ayarlanır?","a":"Büyük pervanelerde titreşimleri azaltmak için FILT değeri 10 yapılır.","o":[["5",false],["10",true],["20",false],["50",false]]},{"m":"MOT_BAT_CURR_MAX parametresinde yazılan akım aşılırsa Pixhawk ne yapar?","a":"Değer 0 ise özellik kapalıdır; Pixhawk akım sınırını aşmamak için gazı kısar.","o":[["Aracı otomatik indirir",false],["Bataryanın bu akımda 5 saniyeden fazla kalmaması için gaz değerini düşürür",true],["Autotune'u iptal eder",false],["Motorları tamamen kapatır",false]]},{"m":"Videoda 4S batarya için MOT_BAT_VOLT_MAX ve MOT_BAT_VOLT_MIN değerleri sırasıyla kaçtır?","a":"Hücre başına tam dolu 4.2 V (4S = 16.8 V), alt sınır 3.2 V (4S = 12.8 V).","o":[["14.8 V ve 10.0 V",false],["16.8 V ve 12.8 V",true],["12.6 V ve 9.6 V",false],["25.2 V ve 19.2 V",false]]},{"m":"Autotune anahtarı açıldığında autotune'un başlayabilmesi için ne gerekir?","a":"Çubuklar ortada değilse veya trim nötr değilse autotune başlamaz.","o":[["Gaz kolu en yukarıda olmalı",false],["Tüm çubuklar ortada ve trimler nötr olmalı",true],["Telemetri bağlı olmalı",false],["Pil tam dolu olmalı",false]]},{"m":"Autotune bittikten sonra yeni PID değerlerinin kaydedilmesi nasıl sağlanır?","a":"Anahtar kapatılırsa eski PID'lere dönülür; anahtar açıkken inip disarm edilince yeni PID'ler kaydedilir.","o":[["Anahtar kapatılır, böylece yeni değerler kaydedilir",false],["Anahtarı kapatmadan yere inilip disarm edilir",true],["Mission Planner'da Save to EEPROM tuşuna basılır",false],["Pil sökülür",false]]},{"m":"Videodaki hekzakopterde toplanabilir iniş takımı hangi çıkışlara bağlanabilir?","a":"MAIN OUT'ların ilk 6'sı hekzakopterin motorlarında kullanıldığı için AUX çıkışları kullanılır.","o":[["Yalnızca MAIN OUT 1-6",false],["AUX 1-4'ten herhangi birine (AUX 5 ve 6 olmaz)",true],["Yalnızca AUX 5 ve 6'ya",false],["Yalnızca TELEM 2'ye",false]]},{"m":"Parametre listesinde AUX1 çıkışı hangi SERVO parametresine karşılık gelir?","a":"İlk 8 servo MAIN OUT'a, SERVO9 ve sonrası AUX çıkışlarına karşılık gelir.","o":[["SERVO1",false],["SERVO7",false],["SERVO9",true],["SERVO14",false]]},{"m":"SERVO9 çıkışını iniş takımına atamak için fonksiyon değeri kaç yapılır?","a":"0 çıkışın devre dışı olduğunu gösterir; landing gear için 29 girilir.","o":[["0",false],["10",false],["29",true],["33",false]]},{"m":"Pixhawk ilk açıldığında anahtar iniş takımını toplama konumundaysa ne olur?","a":"Yerdeyken anahtara yanlışlıkla dokunulursa bacakların kapanıp zarar görmesini önleyen bir güvenlik önlemidir.","o":[["Bacaklar hemen toplanır",false],["İlk komut bacaklara uygulanmaz, ikinci komutla toplanmaya başlar (güvenlik önlemi)",true],["Pixhawk arm olmaz",false],["Bacaklar sürekli açılıp kapanır",false]]},{"m":"LGR_SERVO_DEPLOY ve LGR_SERVO_RETRACT ayarlarıyla Pixhawk iniş sırasında ve uçuşta bacaklara hangi PWM değerlerini gönderir?","a":"HML650 için 1100 iniş (deploy), 1900 toplama (retract) konumudur; tersi mekanizmaya göre çevrilebilir.","o":[["İniş 1900, uçuş 1100",false],["İniş 1100, uçuş 1900",true],["İkisi de 1500",false],["İniş 1000, uçuş 2000",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

commit;
